// Package nodefilter drops each node type that an application does not name
// from the generated file of a node package.
//
// `flutter/ui` holds 1 Go struct for each widget constructor of Flutter: 273
// in the core pack, 218 in Material, and 75 in Cupertino. The emitter writes a
// Dart class and a type descriptor for each 1, and the descriptor of a widget
// that the application never builds is dead weight.
//
// The filter reads each file that nodegen wrote, and it keeps the types of the
// name set. The result replaces the file through the overlay of the load, thus
// the file on disk never changes and 2 applications of 1 checkout each hold
// their own set. The Go type checker then reads the filtered source: an
// application that names a type outside the set gives a plain compile error,
// and no build reads a stale file.
package nodefilter

import (
	"bytes"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

// Mark stands on the first line of each file that nodegen writes.
const Mark = "// Code generated by nodegen."

// Sources gives the filtered source of each generated file under root. A key
// is the path of the file on disk, and the value is the source that the
// compiler reads.
//
// keep holds the name of each type that the application names. The set carries
// a plain name and no import path, exactly as `flutter/nodescan` writes it and
// as the host of nodegen reads it. A name that 2 packs both declare thus stays
// in both, and that answer is safe.
func Sources(root string, keep []string) (map[string][]byte, error) {
	want := map[string]bool{}
	for _, n := range keep {
		want[n] = true
	}
	out := map[string][]byte{}
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
		if err != nil || !entry.IsDir() {
			return err
		}
		return filterDir(path, want, out)
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// pack holds the parsed files of 1 directory.
type pack struct {
	fset *token.FileSet
	// made lists each file that nodegen wrote, in the order of the name.
	made []*ast.File
	// paths gives the path of each file of made.
	paths []string
	// other lists each hand written file of the package.
	other []*ast.File
}

// filterDir writes the filtered source of each generated file of 1 directory
// into out. A directory that holds no such file gives no entry.
//
// A hand written file of the package can name a generated type, and a type of
// the set can name another 1. The keep set thus grows until it holds each name
// that a kept declaration reads.
//
// A test file stays out of the walk. The compiler reads no test file of a
// dependency, thus a type that only a test names is dead weight too.
func filterDir(dir string, want map[string]bool, out map[string][]byte) error {
	p, err := readPack(dir)
	if err != nil || len(p.made) == 0 {
		return err
	}
	keep := map[string]bool{}
	for n := range want {
		keep[n] = true
	}
	for _, f := range p.other {
		readNames(f, keep)
	}
	declared := map[string]bool{}
	for _, f := range p.made {
		for name := range typeNames(f) {
			declared[name] = true
		}
	}
	grow(p.made, declared, keep)
	for i, f := range p.made {
		text, err := write(p.fset, f, declared, keep)
		if err != nil {
			return err
		}
		out[p.paths[i]] = text
	}
	return nil
}

// readPack parses each Go file of a directory that holds no test.
func readPack(dir string) (*pack, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	p := &pack{fset: token.NewFileSet()}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		path := filepath.Join(dir, name)
		src, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		f, err := parser.ParseFile(p.fset, path, src, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		if bytes.HasPrefix(src, []byte(Mark)) {
			p.made = append(p.made, f)
			p.paths = append(p.paths, path)
			continue
		}
		p.other = append(p.other, f)
	}
	return p, nil
}

// typeNames gives the name of each type that a file declares.
func typeNames(f *ast.File) map[string]bool {
	out := map[string]bool{}
	for _, d := range f.Decls {
		gen, ok := d.(*ast.GenDecl)
		if !ok || gen.Tok != token.TYPE {
			continue
		}
		for _, spec := range gen.Specs {
			if ts, ok := spec.(*ast.TypeSpec); ok {
				out[ts.Name.Name] = true
			}
		}
	}
	return out
}

// readNames adds each identifier of a node of the syntax tree to the set.
//
// The name of a struct field, the name of a parameter, and the field of a
// selector each stay out. Such a name is no type, and `Opacity float64` of the
// node type Opacity would otherwise keep that type in each application.
func readNames(n ast.Node, out map[string]bool) {
	ast.Inspect(n, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.Ident:
			out[n.Name] = true
		case *ast.Field:
			readNames(n.Type, out)
			return false
		case *ast.SelectorExpr:
			readNames(n.X, out)
			return false
		}
		return true
	})
}

// grow adds each declared type that a kept declaration names, until the set
// holds no new name.
func grow(files []*ast.File, declared, keep map[string]bool) {
	for {
		added := false
		for _, f := range files {
			for _, d := range f.Decls {
				if !kept(d, declared, keep) {
					continue
				}
				read := map[string]bool{}
				readNames(d, read)
				for name := range read {
					if declared[name] && !keep[name] {
						keep[name] = true
						added = true
					}
				}
			}
		}
		if !added {
			return
		}
	}
}

// kept reports whether a declaration stays in the filtered file.
//
// A type declaration stays when the set holds its name. A method stays when
// the set holds the name of its receiver type. Each other declaration stays,
// because it declares no node type.
func kept(d ast.Decl, declared, keep map[string]bool) bool {
	switch d := d.(type) {
	case *ast.GenDecl:
		if d.Tok != token.TYPE {
			return true
		}
		for _, spec := range d.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok || !declared[ts.Name.Name] || keep[ts.Name.Name] {
				return true
			}
		}
		return false
	case *ast.FuncDecl:
		name := receiverName(d)
		if name == "" || !declared[name] {
			return true
		}
		return keep[name]
	}
	return true
}

// receiverName gives the name of the receiver type of a method. It gives an
// empty text for a function that holds no receiver.
func receiverName(d *ast.FuncDecl) string {
	if d.Recv == nil || len(d.Recv.List) != 1 {
		return ""
	}
	t := d.Recv.List[0].Type
	if star, ok := t.(*ast.StarExpr); ok {
		t = star.X
	}
	if id, ok := t.(*ast.Ident); ok {
		return id.Name
	}
	return ""
}

// write gives the source of the file with each dropped declaration removed.
func write(fset *token.FileSet, f *ast.File, declared, keep map[string]bool) ([]byte, error) {
	cmap := ast.NewCommentMap(fset, f, f.Comments)
	var decls []ast.Decl
	for _, d := range f.Decls {
		if !kept(d, declared, keep) {
			delete(cmap, d)
			continue
		}
		if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.TYPE {
			var specs []ast.Spec
			for _, spec := range gen.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if ok && declared[ts.Name.Name] && !keep[ts.Name.Name] {
					delete(cmap, spec)
					continue
				}
				specs = append(specs, spec)
			}
			gen.Specs = specs
		}
		decls = append(decls, d)
	}
	f.Decls = decls
	f.Comments = cmap.Filter(f).Comments()
	var b bytes.Buffer
	if err := format.Node(&b, fset, f); err != nil {
		return nil, err
	}
	return b.Bytes(), nil
}
